Json CombatScene::captureWarehouseState() const{return WarehouseSaveState::capture(*this);}
void CombatScene::restoreWarehouseState(const Json& j){WarehouseSaveState::restore(*this,j);}
bool CombatScene::directSavePending(const SaveRequest& r) const{return active_&&directSave_&&r.kind=="direct_unscored"&&r.scene==generation_&&r.scene==directSave_->scene&&r.request==directSave_->request&&r.object==directSave_->object&&r.kind==directSave_->kind;}
bool CombatScene::finishDirectSave(const SaveRequest& r){if(!directSavePending(r)){return false;}directSave_.reset();return true;}
