 need(j.at("effects").is_array()&&j.at("effects").size()<=100,"Warehouse effect count");for(const auto& e:j.at("effects")){array(e,7);const bool animation=boolean(e[3]);need(c.media.at(animation?"animations":"effects").contains(string(e[0])),"Unknown warehouse effect");grid(e[1]);integer(e[2],0,360000);actorId(e[4]);if(!animation&&c.media.at("effects").at(e[0].get<std::string>()).at("anchor")=="actor-screen-position-each-stage"){need(!string(e[4]).empty(),"Warehouse actor-anchored effect needs a live actor");}boolean(e[5]);boolean(e[6]);}
