Json WarehouseSaveState::pendingVisual(const CombatScene& s){Json result=Json::array();for(const auto& e:s.presentation_){int kind=-1;if(e.kind==PresentationEvent::Kind::Cue){const auto k=s.content_.cue(e.id).at("kind").get<std::string>();if(k=="show_picture"||k=="move_picture"||k=="erase_picture"||k=="animation"){kind=0;}}else if(e.kind==PresentationEvent::Kind::Effect){kind=1;}else if(e.kind==PresentationEvent::Kind::Animation){kind=2;}if(kind>=0){result.push_back({kind,e.id,xy(e.position),e.actor,e.sampledScreenPosition?xy(*e.sampledScreenPosition):Json(),e.pictureMapOrigin?xy(*e.pictureMapOrigin):Json()});}}return result;}
Json CombatScene::pendingWarehouseVisual() const{return WarehouseSaveState::pendingVisual(*this);}
